private data class Artwork(val path: String, val viewport: Float, val topOffset: Float = 0f)

/** Brand logos use their recognizable official brand color; surrounding buttons stay themed. */
@Composable
internal fun ExternalBrandArtwork(action: ContactAction, modifier: Modifier = Modifier.size(23.dp)) {
    val artwork = when (action) {
        ContactAction.GOOGLE_MAPS -> Artwork(ExternalArtworkPaths.Googlemaps, 24f)
        ContactAction.WAZE -> Artwork(ExternalArtworkPaths.Waze, 24f)
        ContactAction.WHATSAPP -> Artwork(ExternalArtworkPaths.Whatsapp, 24f)
        ContactAction.TELEGRAM -> Artwork(ExternalArtworkPaths.Telegram, 24f)
        ContactAction.VIBER -> Artwork(ExternalArtworkPaths.Viber, 24f)
    }
    val color = when (action) {
        ContactAction.GOOGLE_MAPS -> Color(0xFF4285F4)
        ContactAction.WAZE -> Color(0xFF00A9E0)
        ContactAction.WHATSAPP -> Color(0xFF25D366)
        ContactAction.TELEGRAM -> Color(0xFF26A5E4)
        ContactAction.VIBER -> Color(0xFF7360F2)
    }
    ArtworkCanvas(artwork, color, modifier)
}

/** Exact requested Material Symbols Rounded, with independently themed status tint. */
@Composable
internal fun RequestedWorkArtwork(status: String, color: Color, modifier: Modifier = Modifier.size(24.dp)) {
    val artwork = when (status) {
        "in_progress" -> Artwork(WorkArtworkPaths.BuildCircle, 960f, 960f)
        "paused" -> Artwork(WorkArtworkPaths.PauseCircle, 960f, 960f)
        "approved" -> Artwork(WorkArtworkPaths.PlaylistAddCheckCircle, 960f, 960f)
        "cancelled" -> Artwork(WorkArtworkPaths.HighlightOff, 24f)
        "rework" -> Artwork(WorkArtworkPaths.ResetWrench, 960f, 960f)
        else -> return
    }
    ArtworkCanvas(artwork, color, modifier)
}

@Composable
private fun ArtworkCanvas(artwork: Artwork, color: Color, modifier: Modifier) {
    val path = remember(artwork.path) { PathParser().parsePathString(artwork.path).toPath() }
    Canvas(modifier) {
        val ratio = size.width / artwork.viewport
        // All artwork is square. Material Symbols use viewBox="0 -960 960 960".
        withTransform({
            scale(ratio, size.height / artwork.viewport, pivot = Offset.Zero)
            if (artwork.topOffset > 0f) translate(top = artwork.topOffset)
        }) { drawPath(path, color = color) }
    }
}
